    if (ParseFileName(files[i].substr(1), &number, &type)) {
      if (type == kDescriptorFile) {
        if (number > manifest_number) {
          manifest_number = number;
          ASSERT_GE(size, manifest_size);
          size = manifest_size; // copy only valid MANIFEST data
        }
      }

