        env->GetFileSize(dbname + "/" + file, &file_size);
        char str[8];
        snprintf(str, sizeof(str), "%lu", file_size);
        wal_info.append(file).append(" size: ").
            append(str, sizeof(str)).append(" ;");
        break;
      case kTableFile:
        if (++file_num < 10) {
          file_info.append(file).append(" ");
        }
        break;
      default:
