+// Private structure, exposed only by pointer
+struct DIR {
+    intptr_t               handle_;
+    bool                   firstread_;
+    struct __finddata64_t  data_;
+    dirent                 entry_;
+
+    DIR() : handle_(-1), firstread_(true) {}
+
+    DIR(const DIR&) = delete;
+    DIR& operator=(const DIR&) = delete;
+
+    ~DIR() {
+
+        if (-1 != handle_) {
+            _findclose(handle_);
+        }
+    }
+};
