+
+DIR* opendir(const char* name) {
+
+    if (!name || *name == 0) {
+        errno = ENOENT;
+        return nullptr;
+    }
+
+    std::string pattern(name);
+    pattern.append("\\").append("*");
+
+    std::unique_ptr<DIR> dir(new DIR);
+
+    dir->handle_ = _findfirst64(pattern.c_str(), &dir->data_);
+
+    if (dir->handle_ == -1) {
+        return nullptr;
+    }
+
+    strncpy_s(dir->entry_.d_name, dir->data_.name, strlen(dir->data_.name));
+
+    return dir.release();
+}
+
+struct dirent* readdir(DIR* dirp) {
+
+    if (!dirp || dirp->handle_ == -1) {
+        errno = EBADF;
+        return nullptr;
+    }
+
+    if (dirp->firstread_) {
+        dirp->firstread_ = false;
+        return &dirp->entry_;
+    }
+
+    auto ret = _findnext64(dirp->handle_, &dirp->data_);
+
+    if (ret != 0) {
+        return nullptr;
+    }
+
+    strncpy_s(dirp->entry_.d_name, dirp->data_.name, strlen(dirp->data_.name));
+
+    return &dirp->entry_;
+}
+
+int closedir(DIR* dirp) {
+    delete dirp;
+    return 0;
+}
+
+int truncate(const char* path, int64_t len) {
+
+  if (path == nullptr) {
+    errno = EFAULT;
+    return -1;
+  }
+
+  if (len < 0) {
+    errno = EINVAL;
+    return -1;
+  }
+
+  HANDLE hFile = CreateFile(path,
+    GENERIC_READ | GENERIC_WRITE,
+    0, // No sharing while truncating
+    NULL, // Security attrs
+    OPEN_EXISTING, // Truncate existing file only
+    FILE_ATTRIBUTE_NORMAL,
+    NULL);
+
+  if (INVALID_HANDLE_VALUE == hFile) {
+    auto lastError = GetLastError();
+    if (lastError == ERROR_FILE_NOT_FOUND) {
+      errno = ENOENT;
+    } else if (lastError == ERROR_ACCESS_DENIED) {
+      errno = EACCES;
+    } else {
+      errno = EIO;
+    }
+    return -1;
+  }
+
+  int result = 0;
+  FILE_END_OF_FILE_INFO end_of_file;
+  end_of_file.EndOfFile.QuadPart = len;
+
+  if (!SetFileInformationByHandle(hFile,
+        FileEndOfFileInfo,
+        &end_of_file,
+        sizeof(FILE_END_OF_FILE_INFO))) {
+    errno = EIO;
+    result = -1;
+  }
+
+  CloseHandle(hFile);
+  return result;
+}
