   if (!cmdObj->ValidateCmdLineOptions()) {
     exit(1);
   }

   cmdObj->Run();
   LDBCommandExecuteResult ret = cmdObj->GetExecuteState();
   fprintf(stderr, "%s\n", ret.ToString().c_str());
   delete cmdObj;

