 void DBIter::Next() {
   assert(valid_);

   if (direction_ == kReverse) {
     FindNextUserKey();
     direction_ = kForward;
     if (!iter_->Valid()) {
       iter_->SeekToFirst();
     }
   }

   // If the current value is merged, we might already hit end of iter_
   if (!iter_->Valid()) {
     valid_ = false;
     return;
   }
   FindNextUserEntry(true /* skipping the current user key */);
   if (statistics_ != nullptr) {
