 bool DBImpl::MCOverlap(ManualCompaction* m, ManualCompaction* m1) {
   if ((m->exclusive) || (m1->exclusive)) {
     return true;
   }
   if (m->cfd != m1->cfd) {
     return false;
   }
   return true;
