+  //   -- Examples
+  //     -- a filter that keeps all key-value pairs
+  //     function Filter(level, key, existing_value)
+  //       return false, false, ""
+  //     end
+  //
+  //     -- a filter that keeps all keys and change their values to "Rocks"
