                    std::min(tmp.size() - offset_advance, n));
     }
     *result = Slice(scratch, r);
 #endif  // !ROCKSDB_LITE
   } else {
     s = file_->Read(n, result, scratch);
   }
   IOSTATS_ADD(bytes_read, result->size());
   return s;
