             }
           }
           // Truncate the result
-          case 2:
+          case ErrorType::kErrorTypeTruncated:
           {
             assert(result->size() > 0);
             uint64_t offset = ctx->rand.Uniform((uint32_t)result->size());
             assert(offset < result->size());
             *result = Slice(result->data(), offset);
             break;
           }
           default:
             assert(false);
         }
         break;
       }
       case kOpen:
         return IOStatus::IOError();
       default:
         assert(false);
     }
   }
   return IOStatus::OK();
