  SyncPoint::GetInstance()->EnableProcessing();
  SyncPoint::GetInstance()->EnableProcessing();

  external_file = sst_files_dir_ + "/file_to_ingest2.sst";
  {
    SstFileWriter sst_file_writer{EnvOptions(), CurrentOptions()};

    ASSERT_OK(sst_file_writer.Open(external_file));
