  ASSERT_NOK(registry->NewUniqueObject<Env>("a://test", &guard));
  ASSERT_EQ(guard.get(), b_env);  // Unchanged
  ASSERT_EQ(2, num_a);            // Created one but rejected it as not unique
  ASSERT_EQ(3, num_b);
}

